class Solution:
    def findKOr(self, nums, k):
        cnt = [0] * 31
        for x in nums:
            b = 0
            while x:
                cnt[b] += x & 1
                x >>= 1
                b += 1
        return sum(1 << b for b in range(31) if cnt[b] >= k)

